// Characterization tests: pin CURRENT behaviour of order totals, bugs included.
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

async function withApp(prices, fn) {
  const pricing = { priceOf: async (sku) => prices[sku] }
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { return await fn(base) } finally { await new Promise((r) => server.close(r)) }
}

const post = (base, body) => fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify(body) })

async function totalFor(prices, items) {
  return withApp(prices, async (base) => {
    const res = await post(base, { items })
    assert.equal(res.status, 201)
    return (await res.json()).total
  })
}

const cases = [
  // [description, prices, items, expected total]
  ['single small item', { a: 10 }, [{ sku: 'a', qty: 1 }], 10],
  ['multiple lines are summed', { a: 10, b: 5 }, [{ sku: 'a', qty: 2 }, { sku: 'b', qty: 3 }], 35],
  ['exactly 100: no discount (threshold is strict >)', { a: 100 }, [{ sku: 'a', qty: 1 }], 100],
  ['just above 100: 10% off, then floored', { a: 100.5 }, [{ sku: 'a', qty: 1 }], 90],
  ['101 -> 90.9 floored to 90 (truncates, not rounds)', { a: 101 }, [{ sku: 'a', qty: 1 }], 90],
  ['200 -> 180', { a: 100 }, [{ sku: 'a', qty: 2 }], 180],
  ['large order 1000 -> 900', { a: 10 }, [{ sku: 'a', qty: 100 }], 900],
  ['flat 10% regardless of size (no tiers)', { a: 1 }, [{ sku: 'a', qty: 10000 }], 9000],
  ['fractional total floored: 99.99 -> 99', { a: 99.99 }, [{ sku: 'a', qty: 1 }], 99],
  ['cents are dropped: 19.99 x 3 = 59.97 -> 59', { a: 19.99 }, [{ sku: 'a', qty: 3 }], 59],
  ['discount applies to whole order after summing lines', { a: 60, b: 41 }, [{ sku: 'a', qty: 1 }, { sku: 'b', qty: 1 }], 90],
  ['qty 0 contributes nothing', { a: 10 }, [{ sku: 'a', qty: 0 }], 0],
  ['negative qty reduces total (no validation)', { a: 10 }, [{ sku: 'a', qty: -2 }], -20],
]

for (const [name, prices, items, expected] of cases) {
  test(`total: ${name}`, async () => {
    assert.equal(await totalFor(prices, items), expected)
  })
}

test('unknown sku price yields null total (NaN serialised) ', async () => {
  assert.equal(await totalFor({}, [{ sku: 'x', qty: 1 }]), null)
})

test('order is stored and retrievable with same total', async () => {
  await withApp({ a: 100 }, async (base) => {
    const created = await (await post(base, { items: [{ sku: 'a', qty: 2 }] })).json()
    assert.deepEqual(created, { id: created.id, items: [{ sku: 'a', qty: 2 }], total: 180 })
    const res = await fetch(`${base}/orders/${created.id}`)
    assert.equal(res.status, 200)
    assert.deepEqual(await res.json(), created)
  })
})

test('ids are sequential strings', async () => {
  await withApp({ a: 1 }, async (base) => {
    const a = await (await post(base, { items: [{ sku: 'a', qty: 1 }] })).json()
    const b = await (await post(base, { items: [{ sku: 'a', qty: 1 }] })).json()
    assert.equal(Number(b.id), Number(a.id) + 1)
    assert.equal(typeof a.id, 'string')
  })
})

test('validation: missing/empty items -> 400', async () => {
  await withApp({}, async (base) => {
    for (const body of [{}, { items: [] }, { items: 'x' }]) {
      const res = await post(base, body)
      assert.equal(res.status, 400)
      assert.deepEqual(await res.json(), { error: 'items required' })
    }
  })
})

test('unknown order returns 200 (not 404) with error body', async () => {
  await withApp({}, async (base) => {
    const res = await fetch(`${base}/orders/999`)
    assert.equal(res.status, 200)
    assert.deepEqual(await res.json(), { error: 'not found' })
  })
})

test('unknown route -> 404', async () => {
  await withApp({}, async (base) => {
    const res = await fetch(`${base}/nope`)
    assert.equal(res.status, 404)
  })
})
EOF
